/* Static RELs: the game's area modules linked into the executable.
 *
 * Each entry comes from tools/port3ds/rel_link.py and the table generated by
 * port3ds/CMakeLists.txt. The data block holds the REL's data and read-only
 * data, restored from a boot-time snapshot every time the game links the
 * REL, as the GameCube reloads the whole module from the disc. */
#ifndef PORT3DS_REL_STATIC_H
#define PORT3DS_REL_STATIC_H

#include <dolphin/types.h>

typedef struct PortRelStatic {
    const char* name; /* area name, e.g. "gor" */
    void (*prolog)(void);
    void (*epilog)(void);
    void (*unresolved)(void);
    u8* data_start;
    u8* data_end;
    u8* bss_start;
    u8* bss_end;
} PortRelStatic;

extern const PortRelStatic port_rel_table[];
extern const int port_rel_count;

#endif
